import{_ as o,o as a,c as i,a0 as t}from"./chunks/framework.M9bIWcU1.js";const p=JSON.parse('{"title":"CLI Reference & Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"cli-troubleshooting.md","filePath":"cli-troubleshooting.md"}'),n={name:"cli-troubleshooting.md"};function l(r,e,s,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="cli-reference-troubleshooting" tabindex="-1">CLI Reference &amp; Troubleshooting <a class="header-anchor" href="#cli-reference-troubleshooting" aria-label="Permalink to &quot;CLI Reference &amp; Troubleshooting&quot;">​</a></h1><p>This guide details common command configurations, exit codes, and database isolation troubleshooting.</p><hr><h2 id="_1-options-flags" tabindex="-1">1. Options &amp; Flags <a class="header-anchor" href="#_1-options-flags" aria-label="Permalink to &quot;1. Options &amp; Flags&quot;">​</a></h2><h3 id="full-include-expensive-checks" tabindex="-1"><code>--full</code> (Include Expensive Checks) <a class="header-anchor" href="#full-include-expensive-checks" aria-label="Permalink to &quot;`--full` (Include Expensive Checks)&quot;">​</a></h3><ul><li><strong>Behavior</strong>: Runs database mapping, route serialization caching, and Blade compile sandbox tests.</li><li><strong>When to use</strong>: During pre-deployment hooks or post-commit checks.</li><li><strong>Default</strong>: Excluded from default runs to optimize local speed.</li></ul><h3 id="dirty-staged-scoping" tabindex="-1"><code>--dirty</code> (Staged Scoping) <a class="header-anchor" href="#dirty-staged-scoping" aria-label="Permalink to &quot;`--dirty` (Staged Scoping)&quot;">​</a></h3><ul><li><strong>Behavior</strong>: Scans only files currently modified or staged in Git.</li><li><strong>Scope</strong>: App and view paths only.</li></ul><h3 id="strict-ci-cd-gates" tabindex="-1"><code>--strict</code> (CI/CD Gates) <a class="header-anchor" href="#strict-ci-cd-gates" aria-label="Permalink to &quot;`--strict` (CI/CD Gates)&quot;">​</a></h3><ul><li><strong>Behavior</strong>: Commands return a non-zero exit code (<code>Command::FAILURE</code>) if any check fails, halting pipelines.</li></ul><hr><h2 id="_2-troubleshooting-database-connection-issues" tabindex="-1">2. Troubleshooting Database Connection Issues <a class="header-anchor" href="#_2-troubleshooting-database-connection-issues" aria-label="Permalink to &quot;2. Troubleshooting Database Connection Issues&quot;">​</a></h2><p>Several checks (<code>pending-migration</code>, <code>model-table-mapping</code>, <code>policy-mapping</code>, <code>event-listener-mapping</code>) require active DB and Laravel container bindings:</p><h3 id="symptom-database-connection-failed-during-pending-migration-check" tabindex="-1">Symptom: <code>Database connection failed during pending migration check</code> <a class="header-anchor" href="#symptom-database-connection-failed-during-pending-migration-check" aria-label="Permalink to &quot;Symptom: `Database connection failed during pending migration check`&quot;">​</a></h3><ul><li><strong>Root Cause</strong>: The audit is running in a container or CI pipeline where <code>.env</code> database parameters are offline.</li><li><strong>Resolution</strong>: <ol><li>In static environment pipelines, omit the <code>--full</code> option.</li><li>For deployment pipelines, ensure DB configuration variables are active in the build container.</li></ol></li></ul><hr><h2 id="_3-resolving-syntax-compile-failures" tabindex="-1">3. Resolving Syntax Compile Failures <a class="header-anchor" href="#_3-resolving-syntax-compile-failures" aria-label="Permalink to &quot;3. Resolving Syntax Compile Failures&quot;">​</a></h2><h3 id="symptom-syntax-error-inside-compiled-blade-template" tabindex="-1">Symptom: <code>Syntax error inside compiled Blade template</code> <a class="header-anchor" href="#symptom-syntax-error-inside-compiled-blade-template" aria-label="Permalink to &quot;Symptom: `Syntax error inside compiled Blade template`&quot;">​</a></h3><ul><li><strong>Root Cause</strong>: The Blade token compiler successfully parsed structural markup, but the output PHP code failed standard PHP lint evaluation.</li><li><strong>Resolution</strong>: Search the referenced file for unclosed PHP blocks (e.g., mismatching <code>@if</code> / <code>@endif</code> blocks or unclosed parentheses inside directives like <code>@can</code> or <code>@include</code>).</li></ul>',19)])])}const m=o(n,[["render",l]]);export{p as __pageData,m as default};
